python3 -c "
import json
# Load the JSON and search for any AY-1 or yield data for 1982 Aug
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)

# Search through the entire JSON for relevant data
def search_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            search_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, v in enumerate(d):
            search_dict(v, f'{path}[{i}]')
    elif isinstance(d, str):
        if 'Aug' in d and '1982' in d and ('13.' in d or '12.' in d):
            print(f'{path}: {d}')

search_dict(data)"
